/*
 * A new step is a DRAFT (shared: false) at the end of the plan: the learner sees nothing
 * until the coach shares it. The page sends the default title in the reader's language.
 *  - homework from the library is a COPY (SCOPE R4): brief, hand-in list and resources are
 *    copied now, so a later library edit never reaches it. Archived items are refused.
 *  - a check-in gets a copy of the "After a session" form (shared/Checkin forms, DBU-10); the
 *    coach picks another in the builder until it is sent.
 */
(async () => {
  const refuse = (why) => { Outputs.why = why; Outputs.refuse(); };
  try {
    const R = Noodl.Records;
    const q = (c, where) => R.query(c, where, { limit: 1000, plain: true });
    const planId = String(Inputs.planId || '');
    const plans = planId ? await q('Plan', { objectId: { equalTo: planId } }) : [];
    if (plans.length !== 1) return refuse('That plan is no longer there. Reload the page.');
    const kind = String(Inputs.kind || '');
    const firstStatus = { live: 'to_book', homework: 'not_started', checkin: 'scheduled' };
    if (!firstStatus[kind]) return refuse('A step is a live session, homework or a check-in.');
    const steps = await q('Step', { plan: { equalTo: planId } });
    if (steps.length >= 100) return refuse('A plan holds up to 100 steps.');
    const last = steps.reduce((m, s) => Math.max(m, Number(s.position) || 0), 0);

    const step = { plan: planId, learner: plans[0].learner, position: last + 1, kind, shared: false, status: firstStatus[kind] };
    step.title = String(Inputs.title || '').trim().replace(/\s+/g, ' ').slice(0, 140);
    const libId = String(Inputs.libraryItemId || '');
    if (libId) {
      if (kind !== 'homework') return refuse('Only homework comes from the library.');
      const lib = await q('LibraryItem', { objectId: { equalTo: libId } });
      if (lib.length !== 1 || lib[0].archived === true) return refuse('That homework is no longer in the library. Reload the page.');
      Object.assign(step, { title: lib[0].title, fromLibraryItem: libId, brief: lib[0].brief || '', handInChecklist: lib[0].handInChecklist || [], resources: lib[0].resources || [] });
    }
    if (!step.title) return refuse('Give the step a title.');
    if (kind === 'live') step.durationMin = 60;
    if (kind === 'homework' && !libId) Object.assign(step, { brief: '', handInChecklist: [], resources: [] });
    if (kind === 'checkin') {
      const form = (Array.isArray(Inputs.forms) ? Inputs.forms : []).find((f) => f.id === 'after-session');
      if (!form) throw new Error('no after-session form');
      step.form = form;
    }

    const row = await R.create('Step', step, { plain: true });
    Outputs.stepId = row.objectId || row.id;
    Outputs.done();
  } catch (e) {
    console.error('[dbu:addStep]', String((e && e.message) || e));
    Outputs.failed();
  }
})();
